package br.com.conectatea.vinculo.api;
import br.com.conectatea.auditoria.application.AuditLogService; import br.com.conectatea.crianca.domain.Crianca; import br.com.conectatea.crianca.infrastructure.CriancaRepository; import br.com.conectatea.security.AuthenticatedUser; import br.com.conectatea.shared.domain.BusinessRuleException; import br.com.conectatea.usuario.domain.TipoUsuario; import br.com.conectatea.usuario.infrastructure.UsuarioRepository; import br.com.conectatea.vinculo.domain.PedidoPrimeiroGestor; import br.com.conectatea.vinculo.infrastructure.PedidoPrimeiroGestorRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.time.LocalDate; import org.springframework.http.*; import org.springframework.security.access.AccessDeniedException; import org.springframework.security.core.Authentication; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/criancas") @io.swagger.v3.oas.annotations.tags.Tag(name="Crianças")
public class PrimeiroGestorController {
 private final CriancaRepository criancas; private final PedidoPrimeiroGestorRepository pedidos; private final UsuarioRepository usuarios; private final AuditLogService auditoria;
 public PrimeiroGestorController(CriancaRepository c,PedidoPrimeiroGestorRepository p,UsuarioRepository u,AuditLogService a){criancas=c;pedidos=p;usuarios=u;auditoria=a;}
 @PostMapping("/cadastro-responsavel") @ResponseStatus(HttpStatus.CREATED) @Transactional
 public Response cadastrar(Authentication auth,@Valid @RequestBody Request req){var actor=(AuthenticatedUser)auth.getPrincipal();if(actor.tipo()!=TipoUsuario.RESPONSAVEL)throw new AccessDeniedException("Somente responsável inicia validação de gestão");var user=usuarios.findById(actor.id()).filter(u->u.isAtivo()&&u.isEmailConfirmado()).orElseThrow(()->new BusinessRuleException("EMAIL_NOT_CONFIRMED","Confirme o email antes de cadastrar a criança"));if(!req.responsavelLegal())throw new BusinessRuleException("LEGAL_RESPONSIBILITY_REQUIRED","Declaração de responsabilidade legal obrigatória");var child=criancas.save(new Crianca(req.nome(),req.dataNascimento(),req.genero(),req.diagnostico(),req.diagnosticoDetalhes(),req.observacoes()));child.updateStructured(req.escola(),req.escolaridade(),req.cidade(),req.uf(),req.interesses(),req.nivelSuporte());var pedido=pedidos.save(new PedidoPrimeiroGestor(child.getId(),user.getId(),req.parentesco()));auditoria.record(user.getId(),"PEDIDO_PRIMEIRO_GESTOR_CRIADO","PEDIDO_PRIMEIRO_GESTOR",pedido.getId(),child.getId(),null,"SUCESSO",null);return new Response(child.getId(),pedido.getId(),"PENDENTE_VALIDACAO_ADMINISTRATIVA",false);}
 public record Request(@NotBlank String nome,@NotNull @Past LocalDate dataNascimento,String genero,String diagnostico,String diagnosticoDetalhes,String observacoes,String escola,String escolaridade,String cidade,@Pattern(regexp="[A-Z]{2}") String uf,String interesses,@Min(1) @Max(3) Integer nivelSuporte,@NotBlank String parentesco,boolean responsavelLegal){}
 public record Response(Long criancaId,Long pedidoId,String statusGestao,boolean acessoAtivo){}
}
